 if not stat.S_ISREG(prior.st_mode) or stat.S_ISLNK(prior.st_mode) or prior.st_uid!=os.geteuid() or prior.st_nlink!=1 or prior.st_size!=size:raise ValueError("existing")
 digest=hashlib.sha256()
